                                  const statusLabel = getWorkOrderDisplayStatus(issue);
                                  const statusColor = statusLabel === 'COMPLETED'
                                    ? 'bg-emerald-50 text-emerald-700'
                                    : statusLabel === 'IN PROGRESS'
