                          workOrders: issues.filter(i => String(i.propertyId || i.property?._id || i.property?.id) === String(eid)).length || 0,
                          blocks: Array.isArray(editingProperty.blocks) ? editingProperty.blocks.length : (editingProperty.blocks ? 1 : 0),
